steps.script:
GameState.state["factions"]["2"]["detachment"] = "Grav-Assault Force"
GameState.state.players["1"]["cp"] = 0
GameState.state.players["2"]["cp"] = 0
SettingsService.set("auto_allocate_wounds", true)
var txt := StateSerializer._decompress_json(FileAccess.get_file_as_string("res://tests/saves/cus11e_c3_custodes_active.w40ksave"))
var save = JSON.parse_string(txt)
var gs = save.get("game_state", save)
var cal: Dictionary = gs["units"]["U_CALADIUS_GRAV-TANK_E"].duplicate(true)
cal["owner"] = 2
cal["flags"] = {}
cal["models"][0]["position"] = {"x": 320.0, "y": 1800.0}
GameState.state.units["U_CALADIUS_GRAV-TANK_E"] = cal
tree.current_scene._recreate_unit_visuals()
var D = load("res://scripts/codex/custodes/CustodesDetachments.gd")
return "%d %d" % [D.invuln_save(cal, false), D.invuln_save(cal, true)]

var ph = PhaseManager.get_current_phase_instance()
for d in ph.dice_log:
	if str(d.get("context", "")).begins_with("save"):
		print("[cus11e flare] save block: threshold=", d.get("threshold", ""), " invuln=", d.get("using_invuln", false), " ap=", d.get("ap", 0))
		if bool(d.get("using_invuln", false)) and str(d.get("threshold", "")) == "4+":
			return true
return false

var panel = tree.root.get_node("Main").get_node_or_null("HUD_Left/GameLogPanel")
if panel == null:
	for n in tree.root.get_node("Main").find_children("*", "", true, false):
		if n.get("_tab_dice_button") != null:
			panel = n
			break
if panel == null:
	return "panel not found"
panel._tab_dice_button.emit_signal("pressed")
return true
